import { createClient } from 'supabase';
function combos<T>(a:T[],k:number){const out:T[][]=[];function r(s:number,p:T[]){if(p.length===k){out.push([...p]);return}for(let i=s;i<=a.length-(k-p.length);i++){p.push(a[i]);r(i+1,p);p.pop()}}r(0,[]);return out}
const N=(x:any)=>Number(x||0);
function playerUtility(x:any){return N(x.expected_points)+1.5*N(x.p_10_plus)+4*N(x.p_15_plus)+7*N(x.p_20_plus)+0.35*N(x.p_start)+0.20*N(x.confidence)}
Deno.serve(async req=>{const b=await req.json().catch(()=>({})),gw=Number(b.gameweek||1),save=Boolean(b.save_snapshot),valid=Boolean(b.valid_for_backtest);const ks=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');const sb=createClient(Deno.env.get('SUPABASE_URL')!,ks.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false}});try{const {data:mv}=await sb.from('model_versions').select('id,version').eq('is_active',true).single();if(!mv)throw new Error('active model missing');const {data:latest}=await sb.from('model_predictions').select('generated_at').eq('model_version_id',mv.id).eq('gameweek',gw).order('generated_at',{ascending:false}).limit(1).single();if(!latest)throw new Error('predictions missing');const {data:rows,error}=await sb.from('squad_members').select('player_id,players!inner(id,web_name,position,teams!inner(name),model_predictions!inner(expected_points,p_10_plus,p_15_plus,p_20_plus,p_start,confidence,generated_at,gameweek,model_version_id))').eq('active',true);if(error)throw error;const squad:any[]=[];for(const x of rows||[]){const p:any=x.players,arr=Array.isArray(p.model_predictions)?p.model_predictions:[p.model_predictions],pr=arr.find((q:any)=>q&&q.gameweek===gw&&q.model_version_id===mv.id&&q.generated_at===latest.generated_at);if(pr)squad.push({id:p.id,name:p.web_name,position:p.position,team:p.teams?.name||null,...pr,selection_utility:playerUtility(pr)})}if(squad.length!==15)throw new Error(`active squad predictions ${squad.length}/15`);const gks=squad.filter(x=>x.position==='GKP'),field=squad.filter(x=>x.position!=='GKP');let best:any=null;for(const g of gks)for(const c of combos(field,10)){const n=(q:string)=>c.filter(x=>x.position===q).length;if(n('DEF')<3||n('DEF')>5||n('MID')<2||n('MID')>5||n('FWD')<1||n('FWD')>3)continue;const xi=[g,...c],mean=xi.reduce((s,x)=>s+N(x.expected_points),0),utility=xi.reduce((s,x)=>s+N(x.selection_utility),0);if(!best||utility>best.utility||(utility===best.utility&&mean>best.mean))best={utility,mean,xi}}const ids=new Set(best.xi.map((x:any)=>x.id)),bench=squad.filter(x=>!ids.has(x.id)),bg=bench.filter(x=>x.position==='GKP').sort((a,b)=>b.selection_utility-a.selection_utility),bo=bench.filter(x=>x.position!=='GKP').sort((a,b)=>b.selection_utility-a.selection_utility),xp=[...best.xi].sort((a,b)=>b.expected_points-a.expected_points),tail=[...best.xi].sort((a,b)=>b.p_15_plus-a.p_15_plus||b.p_20_plus-a.p_20_plus||b.expected_points-a.expected_points),capPool=[...best.xi].sort((a,b)=>(b.expected_points+2*b.p_10_plus+5*b.p_15_plus+8*b.p_20_plus+0.25*b.p_start)-(a.expected_points+2*a.p_10_plus+5*a.p_15_plus+8*a.p_20_plus+0.25*a.p_start)),cap=capPool[0],vice=capPool.filter(x=>x.id!==cap.id)[0],safe=xp[0],haul=tail[0],ord:any={GKP:0,DEF:1,MID:2,FWD:3};const squadMean=squad.reduce((s,x)=>s+N(x.expected_points),0),squadUtility=squad.reduce((s,x)=>s+N(x.selection_utility),0);const result:any={model_version:mv.version,optimizer_version:'selection_utility_v0.2',gameweek:gw,predictions_generated_at:latest.generated_at,objective:'maximize_XI_selection_utility = xPts + controlled haul upside + lineup security',utility_weights:{p10:1.5,p15:4,p20:7,p_start:0.35,confidence:0.20},xi_expected_points:+best.mean.toFixed(3),xi_selection_utility:+best.utility.toFixed(3),squad_expected_points:+squadMean.toFixed(3),squad_selection_utility:+squadUtility.toFixed(3),starting_xi:best.xi.sort((a:any,b:any)=>ord[a.position]-ord[b.position]).map((x:any)=>({id:x.id,name:x.name,position:x.position,team:x.team,xPts:x.expected_points,p10:x.p_10_plus,p15:x.p_15_plus,p20:x.p_20_plus,utility:+x.selection_utility.toFixed(3)})),bench:[...bg.map((x:any)=>({id:x.id,name:x.name,position:x.position,order:0,xPts:x.expected_points,utility:+x.selection_utility.toFixed(3)})),...bo.map((x:any,i:number)=>({id:x.id,name:x.name,position:x.position,order:i+1,xPts:x.expected_points,utility:+x.selection_utility.toFixed(3)}))],captain:{id:cap.id,name:cap.name,xPts:cap.expected_points,p10:cap.p_10_plus,p15:cap.p_15_plus,p20:cap.p_20_plus},vice:{id:vice.id,name:vice.name,xPts:vice.expected_points,p15:vice.p_15_plus},safe_captain:{id:safe.id,name:safe.name},haul_captain:{id:haul.id,name:haul.name},captain_split:safe.id!==haul.id};if(save){const {error:se}=await sb.from('decision_snapshots').insert({model_version_id:mv.id,gameweek:gw,squad:squad.map(x=>x.id),starting_xi:result.starting_xi,bench_order:result.bench,captain_player_id:cap.id,vice_player_id:vice.id,recommendations:result,snapshot_type:valid?'deadline':'development_post_deadline',valid_for_backtest:valid,optimization_objective:result.objective,notes:valid?'Pre-deadline model snapshot':'Post-deadline development snapshot; exclude from predictive backtest'});if(se)throw se}return Response.json({ok:true,...result})}catch(e){return Response.json({ok:false,error:e instanceof Error?e.message:String(e)},{status:500})}});
